function exportRun(run){checkRun(run);content();const result=JSON.stringify({format:'tang-campaign-save',version:VERSION,contentSignature:signature,origin:clone(run._origin),commands:clone(run._commands),year:run.year,digest:fingerprint(run)});assert(bytes(result)<=MAX_BYTES,'这一条人生存档超过2MB。');return result;}
function safeObject(x,depth=0){assert(depth<=20,'存档层级过深。');if(typeof x==='number')assert(Number.isFinite(x),'存档含无效数字。');if(x&&typeof x==='object')for(const k of Object.keys(x)){assert(!['__proto__','prototype','constructor'].includes(k),'存档含非法字段。');safeObject(x[k],depth+1);}}
