const rules=Object.freeze({version:VERSION,minYear:MIN,maxYear:MAX,factsThrough:FACTS,maxSaveBytes:MAX_BYTES,statsNature:'六项数值、12个月生活储备与每周16小时初值都是游戏设定，不是现实测量。',initialStats:clone(INITIAL),initialResources:{cashMonths:12,freeHours:16},resourceNature:'生活月数是游戏购买力单位；每年列出基本工作收入与生活支出。可支配小时每年重排，未完成约定、试住和明确的亲密安排先留时间；到期自然释放。',maintenance:'没有向固定锚点回归。状态只由实际选择、延迟后果、兑现或失约以及储备不足的具体后果改变。',probabilityNature:'主线选择份额是游戏编排权重；命盘不是现实事件发生率。部分后续带条件和游戏风险，抽取种子固定且可复现。',astroFormula:'原始命盘及原曲线保持原样。年度primaryTheme决定新长线入口；三年前已开始的事优先续写，四化和大限证据随每一阶段保留。',decisions:'每个未来年份至少推进一条持续多年的人物或作品线，并有一次明确选择。最多两条同时推进，三年内必须回来回应。',fictionalCharacters:{colleague:'小岑：本游戏中才认识的合作者',friend:'阿远：本游戏中才认识的朋友',partner:'林舟：只由明确选项建立亲密关系'},boundary:'2100年100岁只是可玩年份边界，不产生死亡或寿命断言。',persistence:'第三版存档保留起点、每次操作和故事指纹；导入从冻结历史与同版内容重新演算，不接收任意改写状态。',trendNature:'游戏推演曲线直接汇总六项状态和可用生活余地，与命盘原始曲线分开。'});
